def stamp(t):
    return t.isoformat().replace('+00:00', 'Z')

def date(s):
    return datetime.fromisoformat(s.replace('Z', '+00:00'))

def digest(b):
    return hashlib.sha256(b).hexdigest()

def runner_hash():
    return digest(Path(__file__).read_bytes())

def dump_json(p, value):
    p.write_text(json.dumps(value, indent=2, allow_nan=False)+'\n', encoding='utf-8')

def dump_csv(p, rows, fields=None):
    rows = list(rows)
    fields = fields or (list(rows[0]) if rows else ['status'])
    with p.open('w', encoding='utf-8', newline='') as f:
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        w.writerows(rows)

def ledger_hash(rows):
    return digest(''.join(json.dumps({k:r[k] for k in ROW_FIELDS}, sort_keys=True,
                                    separators=(',', ':'), allow_nan=False)+'\n'
                          for r in rows).encode())

class GateFailure(RuntimeError):
    pass

def percentile(values, p):
    if not values:
        return None
    ordered = sorted(values)
    x = (len(ordered)-1)*p
    left, right = math.floor(x), math.ceil(x)
    return ordered[left]+(ordered[right]-ordered[left])*(x-left)

def boundaries():
    points = []
    y,m = BEGIN.year, BEGIN.month
    while datetime(y,m,1,tzinfo=UTC) <= FINISH:
        points.append(datetime(y,m,1,tzinfo=UTC))
        y,m = (y+1,1) if m == 12 else (y,m+1)
    return points

def periods():
    result = [(f'YEAR_{y}','calendar',datetime(y,1,1,tzinfo=UTC),min(datetime(y+1,1,1,tzinfo=UTC),FINISH)) for y in range(2005,2027)]
    result += [(f'ERA_{a}_{b-1}','era',datetime(a,1,1,tzinfo=UTC),min(datetime(b,1,1,tzinfo=UTC),FINISH)) for a,b in ((2005,2010),(2010,2016),(2016,2022),(2022,2027))]
    result += [(f'LATEST_{n}Y','recent',FINISH.replace(year=FINISH.year-n),FINISH) for n in (1,2,3,5,10)]
    result += [('CHF_PRE_FLOOR','policy_diagnostic',BEGIN,date('2011-09-06T00:00:00Z')),
               ('CHF_FLOOR_PERIOD','policy_diagnostic',date('2011-09-06T00:00:00Z'),date('2015-01-15T00:00:00Z')),
               ('CHF_2015_01_15','policy_diagnostic',date('2015-01-15T00:00:00Z'),date('2015-01-16T00:00:00Z')),
               ('CHF_AFTER_2015_01_15','policy_diagnostic',date('2015-01-16T00:00:00Z'),FINISH)]
    return result

def describe_case(rule, model, cost, indices, paths, rows, invalid, blocked):
    tag = dict(strategy_id=rule['strategy_id'],rr=rule['rr'],config_id=rule['config_id'],execution_model=model,cost_ticks=cost)
    closed = [r for r in rows if r['r'] is not None]
    closed_values = [r['r'] for r in closed]
    stamps = [(date(r['entry']),date(r['exit']) if r['exit'] else None,r) for r in rows]
    bounds = boundaries()
    months = [dict(tag,month=bounds[n].strftime('%Y-%m'),entry_count=0,exit_count=0,realized_r=0.0,
                   entry_cohort_eventual_r=0.0,entry_cohort_open=0) for n in range(len(bounds)-1)]
    for et,xt,r in stamps:
        bucket = bisect.bisect_right(bounds,et)-1
        months[bucket]['entry_count'] += 1
        if xt is None:
            months[bucket]['entry_cohort_open'] += 1
        else:
            months[bucket]['entry_cohort_eventual_r'] += r['r']
            cashbucket = bisect.bisect_left(bounds,xt)-1
            if not 0 <= cashbucket < len(months):
                raise GateFailure('Exit outside reporting bounds')
            months[cashbucket]['realized_r'] += r['r']
            months[cashbucket]['exit_count'] += 1
    period_rows = []
    posyears = negyears = emptyyears = 0
    for label,kind,a,b in periods():
        entrants = [r for et,xt,r in stamps if a <= et < b]
        settled = [r for et,xt,r in stamps if xt is not None and a < xt <= b]
        cohort = [r for r in entrants if r['r'] is not None]
        cohort_r = sum(r['r'] for r in cohort)
        p = performance(r['r'] for r in settled)
        partial = int(kind == 'calendar' and b == FINISH and FINISH.month != 1)
        period_rows.append(dict(tag,period=label,period_type=kind,start=stamp(a),end=stamp(b),partial_calendar_year=partial,
                                entry_count=len(entrants),entry_cohort_completed=len(cohort),entry_cohort_eventual_r=cohort_r,
                                entry_cohort_open=len(entrants)-len(cohort),exit_count=len(settled),realized_r=p['total_r'],
                                realized_max_dd_r=p['max_closed_dd_r'],
                                open_at_period_end=sum(et <= b and (xt is None or xt > b) for et,xt,r in stamps)))
        if kind == 'calendar' and not partial:
            posyears += cohort_r > 0
            negyears += cohort_r < 0
            emptyyears += not entrants
    cumulative = {k:[0] for k in ('entry_count','exit_count','realized_r')}
    for m in months:
        for k in cumulative:
            cumulative[k].append(cumulative[k][-1]+m[k])
    rolling, worst = [], {}
    for width in (12,24,36):
        candidates = []
        for end in range(width,len(bounds)):
            begin = end-width
            en,ex,cash = [cumulative[k][end]-cumulative[k][begin] for k in cumulative]
            candidates.append(dict(tag,months=width,start=stamp(bounds[begin]),end=stamp(bounds[end]),
                                   entry_count=en,exit_count=ex,realized_r=cash,zero_entry_window=int(en==0),zero_exit_window=int(ex==0)))
        lowest = min(candidates,key=lambda r:r['realized_r'])
        worst.update({f'worst_{width}m_realized_r':lowest['realized_r'],f'worst_{width}m_start':lowest['start'],
                      f'worst_{width}m_end':lowest['end'],f'zero_entry_{width}m_windows':sum(r['zero_entry_window'] for r in candidates)})
        rolling.extend(candidates)
    accepted_paths = [paths[r['signal_index']] for r in rows]
    closed_paths = [paths[r['signal_index']] for r in closed]
    entry_times = [et for et,_,_ in stamps]
    holding = [(date(r['exit'])-date(r['entry'])).total_seconds()/3600 for r in closed]
    stop_sizes = [p['stop']-p['reference_entry'] for p in accepted_paths]
    fractions = [cost*TICK/v for v in stop_sizes]
    streak = max_empty = 0
    for m in months:
        streak = streak+1 if m['entry_count'] == 0 else 0
        max_empty = max(max_empty,streak)
    isolated = [n for n in indices if price_entry(paths[n],cost)[1] is None]
    iso_values = [realized(paths[n],cost) for n in isolated if paths[n]['exit'] is not None]
    iso_stats = performance(iso_values)
    summary = dict(tag,raw_signals=len(indices),eligible_isolated_signals=len(isolated),isolated_completed=len(iso_values),
                   isolated_open=len(isolated)-len(iso_values),isolated_total_r=iso_stats['total_r'],isolated_profit_factor=iso_stats['profit_factor'],
                   geometry_invalid_all_signals=len(indices)-len(isolated),p0_blocked_signals=blocked,invalid_unblocked_entries=len(invalid),
                   open_at_data_end=len(rows)-len(closed),**performance(closed_values),
                   dual_touch_closed=sum(p['dual_touch'] for p in closed_paths),gap_stop_closed=sum(p['gap_stop'] for p in closed_paths),
                   gap_target_closed=sum(p['gap_target'] for p in closed_paths),
                   entry_next_open_gap_count=sum(p['next_open'] is not None and abs(p['next_open']-p['reference_entry']) > 0.5*TICK for p in accepted_paths),
                   entries_before_market_closure=sum((p['next_candle_delay_hours'] or 0) > 0 for p in accepted_paths),
                   median_stop_pips=percentile([v/0.0001 for v in stop_sizes],0.5),
                   median_cost_fraction_reference_risk=percentile(fractions,0.5),p90_cost_fraction_reference_risk=percentile(fractions,0.9),
                   median_holding_hours=percentile(holding,0.5),max_holding_hours=max(holding) if holding else None,
                   maximum_inter_entry_gap_days=max(((b-a).total_seconds()/86400 for a,b in zip(entry_times,entry_times[1:])),default=None),
                   leading_no_entry_days=((entry_times[0] if entry_times else FINISH)-BEGIN).total_seconds()/86400,
                   trailing_no_entry_days=(FINISH-(entry_times[-1] if entry_times else BEGIN)).total_seconds()/86400,
                   zero_entry_months=sum(m['entry_count'] == 0 for m in months),max_consecutive_zero_entry_months=max_empty,
                   positive_complete_entry_years=posyears,negative_complete_entry_years=negyears,zero_entry_complete_years=emptyyears,
                   raw_signal_sha256=digest('\n'.join(paths[n]['signal'] for n in indices).encode()),accepted_ledger_sha256=ledger_hash(rows),**worst)
    return summary, months, rolling, period_rows

# These are new implementations. References are not inputs to these mechanics.
class Gates:
    def __init__(self):
        self.rows = []

    def check(self, name, actual, expected, numeric=False):
        if numeric and expected is not None:
            good = isinstance(actual, (int,float)) and math.isfinite(actual) and abs(actual-float(expected)) <= 1e-10
        else:
            good = actual == expected
        self.rows.append(dict(check=name,passed=bool(good),expected=expected,actual=actual))
        return good

    def require(self):
        bad = [r['check'] for r in self.rows if not r['passed']]
        if bad:
            raise GateFailure(f'{len(bad)} failed gates: '+', '.join(bad[:8]))


def read_csv_bytes(payload):
    return list(csv.DictReader(io.StringIO(payload.decode('utf-8'))))


def check_rows(gates, label, actual, expected, fields=None):
    """Reference CSV values acquire types from independently generated fields."""
    gates.check(label+':rows',len(actual),len(expected))
    for i,(row,ref) in enumerate(zip(actual,expected)):
        names = tuple(row) if fields is None else fields
        if fields is None:
            gates.check(f'{label}:{i}:schema',set(row),set(ref))
        for key in names:
            value = row[key]
            raw = ref.get(key)
            if raw is None or raw == '':
                target = None
            elif isinstance(value,bool):
                target = raw == 'True' if isinstance(raw,str) else raw
            elif isinstance(value,int):
                target = int(raw)
            elif isinstance(value,float):
                target = float(raw)
            else:
                target = raw
            gates.check(f'{label}:{i}:{key}',value,target,numeric=isinstance(value,float))


def load_sources(gates):
    payload = base64.b85decode(REFERENCE_B85)
    gates.check('frozen_reference_SHA256',digest(payload),REFERENCE_SHA256)
    gates.require()
    required = {'file_manifest.json','frozen_definitions.json','frozen_expected_cases.csv',
                'frozen_reference_ledgers.csv','frozen_raw_signal_membership.csv',
                'frozen_signal_trade_paths.csv','source_candles.csv','daily_snapshot.json',
                'daily_indicators_reference.csv','daily_context_reference.csv'}
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        gates.check('reference_zip_integrity',archive.testzip(),None)
        gates.check('reference_member_set',set(archive.namelist()),required)
        gates.check('reference_member_count',len(archive.namelist()),10)
        blobs = {name:archive.read(name) for name in archive.namelist()}
    integrity = json.loads(blobs['file_manifest.json'])
    gates.check('manifest_exact_unique_members',{r['file'] for r in integrity},required-{'file_manifest.json'})
    gates.check('manifest_record_count',len(integrity),9)
    for row in integrity:
        b = blobs[row['file']]
        gates.check('reference_size:'+row['file'],len(b),row['bytes'])
        gates.check('reference_SHA:'+row['file'],digest(b),row['sha256'])
    gates.check('exact_complete_frozen_definitions',json.loads(blobs['frozen_definitions.json']),FROZEN)
    gates.check('immutable_two_rule_design',len(RULES)==2 and all(r['rr']==3.5 for r in RULES)
                and RULES[1]['d1_filter']['threshold']==1.5 and FROZEN['selection']['other_caps_closed_to_further_search'],True)
    gates.require()
    pin = FROZEN['source']
    gates.check('H1_CSV_SHA',digest(blobs['source_candles.csv']),pin['H1_source_csv_sha256'])
    hourly = [(date(r['time']),*(float(r[k]) for k in ('open','high','low','close')))
              for r in read_csv_bytes(blobs['source_candles.csv'])]
    gates.check('H1_count',len(hourly),pin['H1_candles'])
    gates.check('H1_first',stamp(hourly[0][0]),pin['first_H1'])
    gates.check('H1_last',stamp(hourly[-1][0]),pin['last_H1'])
    gates.check('H1_end_exclusive',stamp(FINISH),pin['end_exclusive'])
    geometry = all(BEGIN<=t and t+HOUR<=FINISH and t.minute==t.second==t.microsecond==0
        and all(math.isfinite(v) and v>0 for v in (o,h,l,c))
        and l<=o<=h and l<=c<=h and (i==0 or hourly[i-1][0]<t)
        for i,(t,o,h,l,c) in enumerate(hourly))
    gates.check('H1_order_completion_geometry',geometry,True)
    canonical = '\n'.join(','.join((stamp(t),*(format(v,'.5f') for v in (o,h,l,c)))) for t,o,h,l,c in hourly)
    gates.check('H1_canonical_SHA',digest(canonical.encode()),pin['H1_canonical_OHLC_sha256'])
    daily_payload = blobs['daily_snapshot.json']
    gates.check('D1_snapshot_SHA',digest(daily_payload),pin['D1_snapshot_sha256'])
    snapshot = json.loads(daily_payload)
    metadata = dict(schema='EURCHF_PASS9_D1_SNAPSHOT_V1',provider='OANDA',instrument='EUR_CHF',granularity='D',
                    price='M',smooth=False,dailyAlignment=17,alignmentTimezone='America/New_York',
                    requested_from='2003-01-01T00:00:00Z',requested_to=stamp(FINISH))
    for key,value in metadata.items():
        gates.check('D1_metadata:'+key,snapshot['metadata'].get(key),value)
    daily = [(date(r['time']),*(float(r[k]) for k in ('open','high','low','close')),date(r['end']))
             for r in snapshot['candles']]
    good = True
    for i,(start,o,h,l,c,end) in enumerate(daily):
        ny = start.astimezone(NY)
        good = good and (ny.hour==17 and ny.minute==ny.second==ny.microsecond==0 and end==next_daily_close(start)
              and end<=FINISH and all(math.isfinite(v) and v>0 for v in (o,h,l,c)) and l<=o<=h and l<=c<=h
              and (i==0 or daily[i-1][5]<=start))
    gates.check('D1_order_alignment_completion_geometry',good,True)
    gates.check('D1_count',len(daily),pin['D1_candles'])
    gates.check('D1_first',stamp(daily[0][0]),pin['first_D1'])
    gates.check('D1_last_end',stamp(daily[-1][5]),pin['last_D1_end'])
    gates.require()
    return hourly,daily,blobs,snapshot


def next_daily_close(start):
    local = start.astimezone(NY)
    tomorrow = local.date()+timedelta(days=1)
    return datetime(tomorrow.year,tomorrow.month,tomorrow.day,17,tzinfo=NY).astimezone(UTC)


def audit_sources(hourly,daily,gates):
    times = [b[0] for b in hourly]
    daily_starts = {b[0] for b in daily}
    audit = []
    # Check every fully observed continuous interval against raw D1 OHLC.
    for start,o,h,l,c,end in daily:
        left,right = bisect.bisect_left(times,start),bisect.bisect_left(times,end)
        section = hourly[left:right]
        continuous = bool(section) and section[0][0]==start and section[-1][0]+HOUR==end
        continuous = continuous and all(b[0]-a[0]==HOUR for a,b in zip(section,section[1:]))
        delta = None
        if continuous:
            observed = (section[0][1],max(b[2] for b in section),min(b[3] for b in section),section[-1][4])
            delta = max(abs(a-b) for a,b in zip(observed,(o,h,l,c)))/TICK
        audit.append(dict(daily_start=stamp(start),daily_end=stamp(end),h1_bars=len(section),
                          contiguous_full_H1_interval=int(continuous),maximum_ohlc_difference_ticks=delta,
                          within_one_tick=int(delta<=1+1e-8) if delta is not None else None))
    full = [r for r in audit if r['contiguous_full_H1_interval']]
    gates.check('H1_D1_full_contiguous_intervals',len(full),5616)
    gates.check('H1_D1_full_interval_OHLC_agreement',all(r['within_one_tick'] for r in full),True)
    # Missing daily records cannot be hidden by checking only existing D1 rows.
    groups = defaultdict(list)
    for t,*_ in hourly:
        local = t.astimezone(NY)
        day = local.date() if local.hour>=17 else local.date()-timedelta(days=1)
        start = datetime(day.year,day.month,day.day,17,tzinfo=NY).astimezone(UTC)
        groups[start].append(t)
    for start,observed in groups.items():
        end = next_daily_close(start)
        if observed[0]==start and observed[-1]+HOUR==end and daily[0][0]<=start and end<=daily[-1][5]:
            gates.check('complete_H1_interval_has_D1:'+stamp(start),start in daily_starts,True)
    gates.require()
    return audit


def wilder_series(bars):
    """Independent batch TR array and Wilder recurrence, seed TR1..14."""
    result = [None]*len(bars)
    if len(bars)<=14:
        return result
    ranges = [None]
    for previous,current in zip(bars,bars[1:]):
        hi,lo,prior = current[2],current[3],previous[4]
        ranges.append(max(hi-lo,abs(hi-prior),abs(lo-prior)))
    result[14] = sum(ranges[1:15])/14
    for index in range(15,len(bars)):
        result[index] = (13*result[index-1]+ranges[index])/14
    return result


def daily_features(daily):
    atr = wilder_series(daily)
    ratios = [None]*len(daily)
    previous_valid = []
    for i,value in enumerate(atr):
        if value is not None:
            if len(previous_valid)>=50:
                mean = sum(previous_valid[-50:])/50
                ratios[i] = value/mean if mean>0 else None
            previous_valid.append(value)
    ema = {}
    for period in (150,200,250):
        line = [None]*len(daily)
        if len(daily)>=period:
            line[period-1] = sum(b[4] for b in daily[:period])/period
            weight = 2/(period+1)
            for i in range(period,len(daily)):
                line[i] = weight*daily[i][4]+(1-weight)*line[i-1]
        ema[period] = line
    return atr,ratios,ema


def context_for_signal(daily,indicators,decision):
    # A separate search over immutable candle completion times. Exact equality
    # makes the completed daily close available; a developing bar never is.
    lower,upper = 0,len(daily)
    while lower<upper:
        middle = (lower+upper)//2
        if daily[middle][5]<=decision:
            lower = middle+1
        else:
            upper = middle
    index = lower-1
    row = dict(decision=stamp(decision),daily_index=None,daily_start=None,daily_end=None,daily_age_hours=None,
               daily_close=None,daily_atr14=None,daily_atr_ratio=None,daily_ema150=None,daily_ema200=None,
               daily_ema250=None,common_context_available=0,context_reason='NO_COMPLETED_D1')
    if index<0:
        return row
    atr,ratios,ema = indicators
    start,_,_,_,close,end = daily[index]
    row.update(daily_index=index,daily_start=stamp(start),daily_end=stamp(end),daily_age_hours=(decision-end).total_seconds()/3600,
               daily_close=close,daily_atr14=atr[index],daily_atr_ratio=ratios[index],
               **{f'daily_ema{p}':ema[p][index] for p in (150,200,250)})
    valid = index>=249 and ratios[index] is not None and all(ema[p][index] is not None for p in (150,200,250))
    row.update(common_context_available=int(valid),context_reason='AVAILABLE' if valid else 'INDICATOR_WARMUP_OR_INVALID')
    return row


def quality_eligible(context):
    return bool(context['common_context_available'] and context['daily_atr_ratio'] is not None
                and context['daily_atr_ratio']<=1.5)


def qualifying_geometry(current,previous,atr,prior_high):
    _,opening,high,low,close = current
    _,previous_open,previous_high,previous_low,previous_close = previous
    engulf = previous_close>previous_open and close<opening and opening>=previous_close and close<=previous_open
    if not engulf or atr is None or atr<=0 or high<=low or previous_high<=previous_low:
        return False,None
    details = dict(atr14=atr,prior60_high=prior_high,body_atr=abs(opening-close)/atr,
                   range_atr=(high-low)/atr,abs_high_distance_atr=abs(high-prior_high)/atr,
                   signal_close_location=(close-low)/(high-low),
                   previous_close_location=(previous_close-previous_low)/(previous_high-previous_low))
    r = RULES[0]
    good = (details['body_atr']>=r['body_min_atr'] and details['range_atr']>=r['range_min_atr']
            and details['abs_high_distance_atr']<=r['distance_atr']
            and details['signal_close_location']<=r['signal_close_max']
            and details['previous_close_location']>=r['previous_close_min'])
    return good,details


def identify_original(hourly):
    atr = wilder_series(hourly)
    indices,features = [],[]
    patterns = 0
    for index in range(200,len(hourly)):
        bar,previous = hourly[index],hourly[index-1]
        if not (previous[4]>previous[1] and bar[4]<bar[1] and bar[1]>=previous[4] and bar[4]<=previous[1]):
            continue
        patterns += 1
        prior = max(b[2] for b in hourly[index-60:index])
        good,detail = qualifying_geometry(bar,previous,atr[index],prior)
        if detail is not None:
            features.append(dict(signal_index=index,signal=stamp(bar[0]),qualifies_original=int(good),**detail))
        if good:
            indices.append(index)
    return indices,features,patterns,atr


def isolated_path(hourly,index,model):
    if model not in MODELS:
        raise ValueError('Unknown execution model')
    signal = hourly[index]
    time,_,high,_,reference = signal
    stop = high+10*TICK
    target = reference-3.5*(stop-reference)
    out = dict(signal_index=index,signal=stamp(time),entry=stamp(time+HOUR),reference_entry=reference,
               stop=stop,target=target,next_open=None,next_candle_delay_hours=None,exit_index=None,exit=None,
               exit_price=None,reason='OPEN_AT_DATA_END',dual_touch=0,gap_stop=0,gap_target=0)
    if index+1<len(hourly):
        out['next_open'] = hourly[index+1][1]
        out['next_candle_delay_hours'] = (hourly[index+1][0]-time-HOUR).total_seconds()/3600
    for cursor in range(index+1,len(hourly)):
        time,opening,hi,lo,_ = hourly[cursor]
        hit_stop,hit_target = hi>=stop,lo<=target
        if not hit_stop and not hit_target:
            continue
        exit_time = time+HOUR
        stop_gap = target_gap = False
        if model=='STOP_FIRST_GAP_STRESS' and opening>=stop:
            price = max(opening,stop)
            stop_gap = opening>stop
            reason = 'STOP_GAP' if stop_gap else 'STOP'
            exit_time = time
        elif model=='STOP_FIRST_GAP_STRESS' and opening<=target:
            price,reason,target_gap,exit_time = target,'TARGET_GAP_CAPPED',True,time
        else:
            choose_stop = hit_stop
            if model=='SCREEN_PARITY' and hit_stop and hit_target:
                choose_stop = abs(hi-opening)<=abs(opening-lo)
            price,reason = (stop,'STOP') if choose_stop else (target,'TARGET')
        out.update(exit_index=cursor,exit=stamp(exit_time),exit_price=price,reason=reason,
                   dual_touch=int(hit_stop and hit_target),gap_stop=int(stop_gap),gap_target=int(target_gap))
        return out
    return out


def price_entry(path,cost):
    fill = path['reference_entry']-cost*TICK
    if date(path['entry'])>=FINISH:
        reason = 'ENTRY_AT_OR_AFTER_CUTOFF'
    elif not (0<path['target']<fill<path['stop']):
        reason = 'INVALID_FILL_STOP_TARGET_GEOMETRY'
    else:
        reason = None
    return fill,reason


def realized(path,cost):
    fill,rejection = price_entry(path,cost)
    if rejection or path['exit'] is None:
        return None
    if path['reason']=='STOP':
        return -1.0
    return (fill-path['exit_price'])/(path['stop']-fill)


def execute_p0(rule,indices,paths,model,cost):
    accepted,rejected,occupancy = [],[],[]
    active = None
    for signal_index in indices:
        if active is not None and (active['exit_index'] is None or signal_index<active['exit_index']):
            occupancy.append(dict(signal_index=signal_index,blocking_signal_index=active['signal_index'],
                                  blocking_exit_index=active['exit_index'],reason='P0_OCCUPIED_BEFORE_GEOMETRY'))
            continue
        path = paths[signal_index]
        fill,problem = price_entry(path,cost)
        if problem:
            rejected.append(dict(signal_index=signal_index,reason=problem))
            continue
        accepted.append(dict(config_id=rule['config_id'],execution_model=model,cost_ticks=cost,
            accepted_sequence=len(accepted)+1,signal_index=signal_index,exit_index=path['exit_index'],
            signal=path['signal'],entry=path['entry'],exit=path['exit'],reference_entry=path['reference_entry'],
            historical_fill=fill,stop=path['stop'],target=path['target'],risk_price=path['stop']-fill,
            exit_price=path['exit_price'],reason=path['reason'],r=realized(path,cost)))
        active = path
    return accepted,rejected,occupancy


def performance(numbers):
    values = list(numbers)
    wins = [v for v in values if v>0]
    losses = [v for v in values if v<0]
    equity,peak,minimum,streak,longest = 0.0,0.0,0.0,0,0
    for value in values:
        equity += value
        peak = max(peak,equity)
        minimum = min(minimum,equity-peak)
        streak = streak+1 if value<0 else 0
        longest = max(streak,longest)
    return dict(closed_trades=len(values),wins=len(wins),losses=len(losses),
        win_rate_pct=100*len(wins)/len(values) if values else None,total_r=equity,
        expectancy_r=equity/len(values) if values else None,
        profit_factor=sum(wins)/-sum(losses) if losses else None,
        max_closed_dd_r=minimum,max_losing_streak=longest)


def confirm(hourly,daily,blobs,gates):
    original,features,patterns,h1atr = identify_original(hourly)
    gates.check('raw_bearish_patterns_after_warmup',patterns,9669)
    gates.check('original_raw_signal_count',len(original),59)
    indicators = daily_features(daily)
    atr,ratios,ema = indicators
    series = [dict(daily_index=i,time=stamp(b[0]),end=stamp(b[5]),close=b[4],atr14=atr[i],
                   atr14_prior50_ratio=ratios[i],ema150=ema[150][i],ema200=ema[200][i],ema250=ema[250][i])
              for i,b in enumerate(daily)]
    check_rows(gates,'all_D1_indicators',series,read_csv_bytes(blobs['daily_indicators_reference.csv']))
    contexts = [dict(signal_index=i,signal=stamp(hourly[i][0]),
                     **context_for_signal(daily,indicators,hourly[i][0]+HOUR)) for i in original]
    check_rows(gates,'all_frozen_signal_daily_contexts',contexts,read_csv_bytes(blobs['daily_context_reference.csv']))
    context_map = {r['signal_index']:r for r in contexts}
    filtered = [i for i in original if quality_eligible(context_map[i])]
    eligible = sum(r['common_context_available'] for r in contexts)
    gates.check('primary_common_eligible_count',eligible,59)
    gates.check('quality_raw_signal_count',len(filtered),53)
    membership = {RULES[0]['config_id']:original,RULES[1]['config_id']:filtered}
    raw_rows = [dict(rr=rule['rr'],config_id=rule['config_id'],signal_index=i)
                for rule in RULES for i in membership[rule['config_id']]]
    check_rows(gates,'all_raw_memberships',raw_rows,read_csv_bytes(blobs['frozen_raw_signal_membership.csv']))
    path_map = {(model,i):isolated_path(hourly,i,model) for model in MODELS for i in original}
    path_rows = [dict(config_id=rule['config_id'],rr=rule['rr'],execution_model=model,**path_map[(model,i)])
                 for rule in RULES for model in MODELS for i in membership[rule['config_id']]]
    # Compare complete isolated paths including gap/dual-touch/next-open fields.
    check_rows(gates,'all_isolated_trade_paths',path_rows,read_csv_bytes(blobs['frozen_signal_trade_paths.csv']))
    gates.require()
    names = ['summary.csv','accepted_trades.csv','monthly_results.csv','rolling_windows.csv','period_results.csv',
             'invalid_entries.csv','p0_occupancy.csv','open_at_data_end.csv','chf_event_exposure.csv',
             'influence.csv','concentration.csv','original_quality_comparisons.csv','trade_differences.csv']
    out = {name:[] for name in names}
    out.update({'raw_signal_features.csv':features,'raw_signal_membership.csv':raw_rows,
                'signal_trade_paths.csv':path_rows,'daily_indicators.csv':series,'daily_context.csv':contexts,
                'daily_predicates.csv':[dict(r,passes_quality=int(quality_eligible(r))) for r in contexts],
                'h1_atr14.csv':[dict(index=i,time=stamp(hourly[i][0]),atr14=a) for i,a in enumerate(h1atr)],
                'eligibility_exclusions.csv':[r for r in contexts if not r['common_context_available']]})
    case_rows,case_stats = {},{}
    for rule in RULES:
        indices = membership[rule['config_id']]
        for model in MODELS:
            paths = {i:path_map[(model,i)] for i in indices}
            for cost in COSTS:
                rows,invalid,blocked = execute_p0(rule,indices,paths,model,cost)
                summary,months,rolling,period_rows = describe_case(rule,model,cost,indices,paths,rows,invalid,len(blocked))
                quality = rule['d1_filter'] is not None
                summary.update(role=rule['role'],base_config_id=RULES[0]['config_id'],
                    family='D1_ATR_RATIO_LE' if quality else 'FULL_CONTROL',threshold=1.5 if quality else None,
                    comparison_scope='COMMON_D1_AVAILABLE' if quality else 'FULL_HISTORY',
                    level_role='PROVISIONAL_REPRESENTATIVE' if quality else 'UNCHANGED_PRIMARY',
                    base_raw_signals=len(original),context_excluded_signals=len(original)-eligible,
                    common_available_signals=eligible,
                    research_strategy_id=FROZEN['quality_previous_research_strategy_id'] if quality else rule['strategy_id'])
                key = (rule['config_id'],model,cost)
                case_rows[key],case_stats[key] = rows,summary
                out['summary.csv'].append(summary)
                out['accepted_trades.csv'].extend(dict(rr=rule['rr'],role=rule['role'],strategy_id=rule['strategy_id'],**r) for r in rows)
                out['monthly_results.csv'].extend(months)
                out['rolling_windows.csv'].extend(rolling)
                out['period_results.csv'].extend(period_rows)
                tag = dict(config_id=rule['config_id'],execution_model=model,cost_ticks=cost)
                winners=sorted((r['r'] for r in rows if r['r'] is not None and r['r']>0),reverse=True)
                gross=sum(winners)
                out['concentration.csv'].append(dict(tag,closed_trades=sum(r['r'] is not None for r in rows),
                    winning_trades=len(winners),gross_winning_r=gross,
                    top1_gross_winning_share_pct=100*sum(winners[:1])/gross if gross else None,
                    top3_gross_winning_share_pct=100*sum(winners[:3])/gross if gross else None,
                    top5_gross_winning_share_pct=100*sum(winners[:5])/gross if gross else None))
                out['invalid_entries.csv'].extend(dict(tag,**r) for r in invalid)
                out['p0_occupancy.csv'].extend(dict(tag,**r) for r in blocked)
                for r in rows:
                    if r['exit'] is None:
                        out['open_at_data_end.csv'].append(dict(tag,signal_index=r['signal_index'],entry=r['entry'],
                            stop=r['stop'],target=r['target'],historical_fill=r['historical_fill']))
                    if date(r['entry'])<date('2015-01-16T00:00:00Z') and (r['exit'] is None or date(r['exit'])>date('2015-01-15T00:00:00Z')):
                        out['chf_event_exposure.csv'].append(dict(tag,signal_index=r['signal_index'],entry=r['entry'],exit=r['exit'],r=r['r'],reason=r['reason']))
                    if r['r'] is not None:
                        omitted = performance(x['r'] for x in rows if x['r'] is not None and x['signal_index']!=r['signal_index'])
                        out['influence.csv'].append(dict(tag,signal_index=r['signal_index'],r=r['r'],
                            closed_r_without_trade=omitted['total_r'],maximum_closed_dd_without_trade=omitted['max_closed_dd_r'],
                            interpretation='Arithmetic leave-one-trade-out diagnostic, not a new p0 replay'))
    check_rows(gates,'all_frozen_case_summaries',out['summary.csv'],read_csv_bytes(blobs['frozen_expected_cases.csv']))
    check_rows(gates,'all_frozen_accepted_fields',out['accepted_trades.csv'],read_csv_bytes(blobs['frozen_reference_ledgers.csv']))
    gates.check('accepted_total',len(out['accepted_trades.csv']),672)
    gates.check('case_total',len(out['summary.csv']),12)
    for model in MODELS:
        for cost in COSTS:
            a,b = (case_rows[(r['config_id'],model,cost)] for r in RULES)
            first,second = ({r['signal_index']:r for r in rows} for rows in (a,b))
            removed,added = sorted(first.keys()-second.keys()),sorted(second.keys()-first.keys())
            retained = sorted(first.keys()&second.keys())
            # Filtering renumbers accepted_sequence by design. Full sequence
            # parity is checked against each rule's own frozen ledger above.
            changed = [i for i in retained if any(first[i][k]!=second[i][k] for k in ROW_FIELDS
                                                  if k not in ('config_id','accepted_sequence'))]
            old,new = (case_stats[(r['config_id'],model,cost)] for r in RULES)
            marginal = sum(second[i]['r'] or 0 for i in added)-sum(first[i]['r'] or 0 for i in removed)
            marginal += sum((second[i]['r'] or 0)-(first[i]['r'] or 0) for i in changed)
            gates.check('marginal_cash_identity:'+model+':'+str(cost),new['total_r']-old['total_r'],marginal,numeric=True)
            gates.check('no_added_or_displaced:'+model+':'+str(cost),len(added)+len(changed),0)
            out['original_quality_comparisons.csv'].append(dict(execution_model=model,cost_ticks=cost,
                original_trades=len(a),quality_trades=len(b),removed_trades=len(removed),added_trades=len(added),
                changed_retained_trades=len(changed),original_total_r=old['total_r'],quality_total_r=new['total_r'],
                total_r_delta=new['total_r']-old['total_r'],removed_total_r=sum(first[i]['r'] or 0 for i in removed),
                original_maximum_closed_dd_r=old['max_closed_dd_r'],quality_maximum_closed_dd_r=new['max_closed_dd_r']))
            for i in removed:
                out['trade_differences.csv'].append(dict(execution_model=model,cost_ticks=cost,change='REMOVED',
                    signal_index=i,signal=first[i]['signal'],entry=first[i]['entry'],exit=first[i]['exit'],r=first[i]['r'],
                    daily_atr_ratio=context_map[i]['daily_atr_ratio']))
    for cost in COSTS:
        for rule in RULES:
            a,b = (case_stats[(rule['config_id'],model,cost)] for model in MODELS)
            gates.check('selected_model_return_match:'+rule['role']+str(cost),a['total_r'],b['total_r'],numeric=True)
            gates.check('selected_model_drawdown_match:'+rule['role']+str(cost),a['max_closed_dd_r'],b['max_closed_dd_r'],numeric=True)
    gates.require()
    return out


DESIGN = dict(stage='Independent original versus frozen quality confirmation',rules=2,cases=12,rr=3.5,
              costs_ticks=list(COSTS),execution_models=list(MODELS),automatic_selection=False,parameter_search=False,
              reference_SHA256=REFERENCE_SHA256,history_is_in_sample=True,portfolio_admission_complete=False,
              orders_supported=False,credentials_required=False)
PROTOCOL = '''# EUR/CHF H1 short — Pass11 independent confirmation

Exactly two previously frozen alternatives: original RR3.50 and quality RR3.50
with completed D1 ATR14 / mean(preceding50 valid ATR14, excluding numerator day)
<=1.50 at full precision. No new cap, RR, filter or parameter search.

Reconstruct H1 and D1 indicators, original geometry, causal completed daily
context, raw memberships, isolated barrier paths, adverse entry geometry and p0
from immutable raw sources. Prior accepted rows never generate signals or trades.
Compare every frozen raw membership, isolated path, accepted field and case
summary, plus exact canonical accepted-ledger hashes. Reject any mismatch.

Python standard library only; embedded data-only reference bundle; no imported
prior signal/execution engine or network/broker/credential/order access.
Reporting utilities for calendar windows, quantiles, schema and formatting are
retained to preserve the established report convention. Performance accumulation
and all trading/indicator/source mechanics are independently authored.

2005-01-01 through 2026-10-01 exclusive, OANDA MID unsmoothed. D1 prehistory
starts 2003-01-01 and keeps legacy flat/weekend records as returned;17NY/DST,
only completed end<=H1 close decision. Common ATR and EMA150/200/250 availability
retained, daily warmup250 observations; EMA direction is not an entry filter.
H1 warmup200 observations, Wilder ATR14 seed TR1..14, prior60high excludes signal,
engulf previous bullish, body>=0.75ATR, range>=1.25ATR, ABS(high-priorhigh)<=0.075ATR,
signal close location<=0.35, previous close location>=0.75.

Stop=signalhigh+10ticks. Entry reference=signalclose at timestamp+1hour.
Target=reference-3.50*(stop-reference). Short fill=reference-cost*tick,
tick=0.00001, costs10/20/40ticks(1/2/4assumedpips), risk=stop-fill.
Valid only0<target<fill<stop and entry<cutoff. p0 occupancy checked before geometry,
exit-candle reentry allowed; unresolved positions stay occupied. No reference-row
deletions substitute for replay. Ordinary STOP is exactly-1R. Unresolved trades
have no realized R.

SCREEN_PARITY dualtouch nearer-to-open extreme first, tie STOP, barrier fill and
candle-end exit. STOP_FIRST_GAP_STRESS opening>=stop fills max(open,stop) atopen;
opening<=target cappedtarget atopen; otherwise STOP on dualtouch, barrier/end.

All twelve frozen cases remain visible with complete raw features, indicators,
asof contexts, trade paths, ledgers, accepted hashes, period/month/zero-inclusive
rolling results, inactivity, marginal losses/winners, concentration and source
coverage. Failure publishes only diagnostics; no partial performance bundle.

Independent confirmation concerns reproducibility on repeatedly used in-sample
history, not new out-of-sample performance or independent broker data. Original
remains default. The quality alternative is not admitted to P31 or deployed.
Review returned results, then new exact P31 admission head-to-head at matched
cutoff2026-09-20T18:29Z; Pass8 applies to original only. No portfolio feedback to
choose caps, no stacking alternatives. Prospective execution validation later.
'''


def software_checks():
    tests = []
    def test(name,condition):
        tests.append(dict(check=name,passed=bool(condition)))
        if not condition:
            raise GateFailure('Software control failed: '+name)
    start = date('2020-01-01T00:00:00Z')
    bars = [(start+i*HOUR,1.0,1.01,0.99,1.0) for i in range(300)]
    line = wilder_series(bars)
    test('Wilder_first_valid_index14',all(v is None for v in line[:14]) and line[14] is not None)
    test('Wilder_seed_TR1_to14',abs(line[14]-0.02)<1e-12)
    altered = list(bars); altered[200] = (altered[200][0],1.0,2.0,0.5,1.0)
    test('ATR_prefix_causal',wilder_series(altered)[:200]==line[:200])
    daily = [(start+timedelta(days=i),1.,1.01,0.99,1.,start+timedelta(days=i+1)) for i in range(300)]
    d = daily_features(daily)
    test('ratio_first_valid64',all(v is None for v in d[1][:64]) and d[1][64] is not None)
    test('ratio_uses_preceding50_excluding_numerator',abs(d[1][64]-d[0][64]/(sum(d[0][14:64])/50))<1e-12)
    spike = list(daily); spike[64] = (spike[64][0],1.,2.,0.5,1.,spike[64][5])
    sp = daily_features(spike)
    test('spike_numerator_not_in_denominator',abs(sp[1][64]-sp[0][64]/(sum(d[0][14:64])/50))<1e-12)
    for p in (150,200,250):
        test('EMA_mean_seed_'+str(p),all(v is None for v in d[2][p][:p-1]) and abs(d[2][p][p-1]-1)<1e-12)
    test('NY_spring23hours',next_daily_close(date('2020-03-07T22:00:00Z'))-date('2020-03-07T22:00:00Z')==timedelta(hours=23))
    test('NY_autumn25hours',next_daily_close(date('2020-10-31T21:00:00Z'))-date('2020-10-31T21:00:00Z')==timedelta(hours=25))
    end = daily[260][5]
    test('daily_exact_end_available',context_for_signal(daily,d,end)['daily_index']==260)
    test('daily_future_bar_excluded',context_for_signal(daily,d,end-timedelta(microseconds=1))['daily_index']==259)
    test('daily_no_completed_record',context_for_signal(daily,d,start)['context_reason']=='NO_COMPLETED_D1')
    test('common_warmup_required',context_for_signal(daily,d,daily[248][5])['common_context_available']==0)
    test('common_warmup_ready',context_for_signal(daily,d,daily[249][5])['common_context_available']==1)
    test('cap_inclusive',quality_eligible(dict(common_context_available=1,daily_atr_ratio=1.5)))
    test('cap_full_precision',not quality_eligible(dict(common_context_available=1,daily_atr_ratio=1.50000000001)))
    test('cap_unavailable_excluded',not quality_eligible(dict(common_context_available=0,daily_atr_ratio=1.0)))
    decision = daily[260][5]
    future = list(daily); future[270] = (future[270][0],1.,3.,0.2,2.,future[270][5])
    test('future_daily_change_no_context_change',context_for_signal(future,daily_features(future),decision)==context_for_signal(daily,d,decision))
    previous=(start,1.002,1.009,1.0,1.008)
    current=(start+HOUR,1.008,1.009,0.998,1.0)
    good,feature=qualifying_geometry(current,previous,0.008,1.009)
    test('geometry_base_qualifies',good)
    test('geometry_abs_distance',not qualifying_geometry(current,previous,0.008,1.02)[0])
    test('geometry_previous_bull_required',not qualifying_geometry(current,(start,1.009,1.01,1.0,1.008),0.008,1.009)[0])
    test('H1_warmup_excludes_early_signal',identify_original([previous,current])[0]==[])
    stream=[(start+i*HOUR,1.005,1.009,1.001,1.005) for i in range(205)]
    stream[199]=(stream[199][0],1.002,1.009,1.0,1.008)
    stream[200]=(stream[200][0],1.008,1.0094,0.998,1.0)
    signals,features,_,_=identify_original(stream)
    test('H1_warmup200_inclusive',signals==[200])
    test('prior60_excludes_signal_high',features[0]['prior60_high']==1.009 and features[0]['abs_high_distance_atr']>0)
    early=list(stream);early[198]=stream[199][:1]+stream[199][1:];early[198]=(start+198*HOUR,*early[198][1:])
    early[199]=(start+199*HOUR,*stream[200][1:]);early[200]=(start+200*HOUR,1.005,1.009,1.001,1.005)
    test('H1_signal199_still_excluded',identify_original(early)[0]==[])
    origin=(start,1.,1.001,0.999,1.)
    stop=1.001+10*TICK; target=1.-3.5*(stop-1.)
    def path(opening,hi,lo,model='STOP_FIRST_GAP_STRESS'):
        return isolated_path([origin,(start+HOUR,opening,hi,lo,opening)],0,model)
    gap=path(stop+0.002,stop+0.003,0.999)
    test('stress_gap_stop_price',gap['reason']=='STOP_GAP' and gap['exit_price']==stop+0.002)
    test('stress_gap_time_open',gap['exit']==stamp(start+HOUR))
    targetgap=path(target-0.001,1.,target-0.002)
    test('stress_target_gap_capped',targetgap['reason']=='TARGET_GAP_CAPPED' and targetgap['exit_price']==target)
    dual=path(1.,stop+0.0001,target-0.0001)
    test('stress_dual_stop',dual['reason']=='STOP' and dual['dual_touch']==1)
    test('screen_nearest_upper_stop',path(1.,stop+0.0001,target-0.0001,'SCREEN_PARITY')['reason']=='STOP')
    test('screen_nearest_lower_target',path(1.,stop+0.01,target-0.0001,'SCREEN_PARITY')['reason']=='TARGET')
    test('screen_exact_extreme_tie_stop',path(1.,1.02,0.98,'SCREEN_PARITY')['reason']=='STOP')
    test('screen_exit_candle_end',path(1.,stop+0.0001,0.999,'SCREEN_PARITY')['exit']==stamp(start+2*HOUR))
    ordinary=path(1.,stop+0.0001,0.999)
    test('ordinary_stop_exact_minus1',all(realized(ordinary,c)==-1.0 for c in COSTS))
    test('gap_stop_worse_than_minus1',realized(gap,40)<-1)
    test('adverse_fill_fixed_target',price_entry(ordinary,40)[0]==1.-40*TICK and ordinary['target']==target)
    invalid=dict(ordinary,target=0.9999)
    test('invalid_cost_geometry',price_entry(invalid,40)[1]=='INVALID_FILL_STOP_TARGET_GEOMETRY')
    cutoff=dict(ordinary,entry=stamp(FINISH))
    test('cutoff_exclusive',price_entry(cutoff,10)[1]=='ENTRY_AT_OR_AFTER_CUTOFF')
    openpath=isolated_path([origin],0,'SCREEN_PARITY')
    test('signal_bar_not_execution_bar',openpath['reason']=='OPEN_AT_DATA_END' and realized(openpath,10) is None)
    delayed=isolated_path([origin,(start+3*HOUR,1.,stop+0.001,0.999,1.)],0,MODELS[0])
    test('entry_reference_no_next_open_substitution',delayed['entry']==stamp(start+HOUR) and delayed['reference_entry']==1.
         and delayed['next_candle_delay_hours']==2.)
    p0=dict(ordinary,signal_index=0,exit_index=3)
    p1=dict(invalid,signal_index=1)
    p3=dict(ordinary,signal_index=3,exit_index=4)
    rows,rejected,blocked=execute_p0(RULES[0],[0,1,3],{0:p0,1:p1,3:p3},MODELS[0],40)
    test('p0_before_geometry',len(blocked)==1 and not rejected)
    test('exit_candle_reentry',len(rows)==2 and rows[1]['signal_index']==3)
    rows,rejected,blocked=execute_p0(RULES[0],[0,1],{0:openpath,1:ordinary},MODELS[0],10)
    test('unresolved_occupancy',len(rows)==1 and len(blocked)==1)
    stats=performance([-1.,-1.,3.,-1.])
    test('performance_ordered_drawdown',stats['total_r']==0 and stats['max_closed_dd_r']==-2 and stats['max_losing_streak']==2)
    test('ledger_hash_sensitive',ledger_hash([dict(rows[0],r=0.0)])!=ledger_hash(rows))
    return tests


def data_key():
    return digest(json.dumps(dict(reference=REFERENCE_SHA256,frozen=FROZEN,costs=COSTS,models=MODELS),sort_keys=True).encode())


def read_status():
    try:
        return json.loads((OUT/'status.json').read_text())
    except (OSError,ValueError):
        return dict(state='idle',version=VERSION)


def write_status(state,**values):
    OUT.mkdir(parents=True,exist_ok=True)
    record=dict(state=state,version=VERSION,runner_sha256=runner_hash(),updated=stamp(datetime.now(UTC)),**values)
    with tempfile.NamedTemporaryFile(dir=OUT,mode='w',encoding='utf-8',delete=False) as f:
        json.dump(record,f,allow_nan=False)
        temporary=f.name
    os.replace(temporary,OUT/'status.json')


def publish(work,success):
    diagnostics={'protocol.md','run_manifest.json','error_report.json','parity_checks.csv',
                 'software_checks.csv','runner_source.py','confirmation_design.json'}
    members=[p for p in sorted(work.iterdir()) if p.is_file() and p.name!='file_manifest.json'
             and (success or p.name in diagnostics)]
    dump_json(work/'file_manifest.json',[dict(file=p.name,bytes=p.stat().st_size,sha256=digest(p.read_bytes())) for p in members])
    fd,temporary=tempfile.mkstemp(dir=OUT,suffix='.zip');os.close(fd)
    try:
        with zipfile.ZipFile(temporary,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as archive:
            for member in members+[work/'file_manifest.json']:
                archive.write(member,member.name)
        os.replace(temporary,OUT/RESULT_NAME)
    finally:
        if os.path.exists(temporary):os.unlink(temporary)


def confirmation_job():
    global FILE_LOCK
    success=False; gates=Gates()
    manifest=dict(DESIGN,version=VERSION,status='RUNNING',runner_sha256=runner_hash(),
                  accepted_fields=list(ROW_FIELDS),independent_mechanics=True,
                  broker_refetch=False,prospective_validation_complete=False)
    try:
        with tempfile.TemporaryDirectory(prefix='pass11-',dir=OUT) as folder:
            work=Path(folder)
            (work/'protocol.md').write_text(PROTOCOL)
            (work/'runner_source.py').write_bytes(Path(__file__).read_bytes())
            dump_json(work/'confirmation_design.json',DESIGN)
            try:
                software=software_checks();dump_csv(work/'software_checks.csv',software)
                write_status('running',progress=10,result_path=None,message='Validating exact H1 and D1 sources')
                hourly,daily,blobs,snapshot=load_sources(gates)
                audit=audit_sources(hourly,daily,gates)
                write_status('running',progress=35,result_path=None,message='Independent indicators, raw signals, context and p0 replay')
                output=confirm(hourly,daily,blobs,gates)
                write_status('running',progress=80,result_path=None,message='Publishing complete frozen parity and diagnostic reports')
                empty_fields={
                    'invalid_entries.csv':['config_id','execution_model','cost_ticks','signal_index','reason'],
                    'p0_occupancy.csv':['config_id','execution_model','cost_ticks','signal_index','blocking_signal_index','blocking_exit_index','reason'],
                    'open_at_data_end.csv':['config_id','execution_model','cost_ticks','signal_index','entry','stop','target','historical_fill'],
                    'chf_event_exposure.csv':['config_id','execution_model','cost_ticks','signal_index','entry','exit','r','reason'],
                    'eligibility_exclusions.csv':['signal_index','signal','decision','daily_index','context_reason']}
                for name,rows in output.items():
                    dump_csv(work/name,rows,empty_fields.get(name) if not rows else None)
                dump_csv(work/'daily_coverage_audit.csv',audit)
                for name,payload in blobs.items():
                    if name!='file_manifest.json':
                        (work/('reference_'+name if name.endswith('.csv') and name!='source_candles.csv' else name)).write_bytes(payload)
                dump_json(work/'source_pins.json',FROZEN['source'])
                dump_json(work/'daily_source_metadata.json',snapshot['metadata'])
                dump_json(work/'independence_statement.json',dict(
                    independently_authored=['load_sources','audit_sources','wilder_series','daily_features','context_for_signal',
                        'quality_eligible','qualifying_geometry','identify_original','isolated_path','price_entry','realized','execute_p0','performance'],
                    reused_report_only=['stamp','date','digest','runner_hash','dump_json','dump_csv','ledger_hash','percentile','boundaries','periods','describe_case'],
                    references_used_only_after_independent_generation=True,
                    independent_broker_data=False,new_out_of_sample_data=False,portfolio_admission_complete=False))
                gates.require()
                manifest.update(status='COMPLETE',cases=12,h1_candles=len(hourly),d1_candles=len(daily),
                    full_raw_membership_parity=True,full_isolated_path_parity=True,full_accepted_ledger_parity=True,
                    exact_accepted_hash_parity=True,all_case_summary_parity=True,daily_indicator_and_context_parity=True,
                    software_checks=len(software),runtime_gates=len(gates.rows),
                    output_row_counts={k:len(v) for k,v in output.items()},
                    next='Review returned confirmation; then new exact original-versus-quality P31 admission. Original remains default.')
                success=True
            except Exception as exc:
                manifest.update(status='ERROR',error=str(exc))
                dump_json(work/'error_report.json',dict(error=str(exc),traceback=traceback.format_exc(),
                    interpretation='Failed source/parity/reporting gate; do not interpret partial results.'))
            dump_csv(work/'parity_checks.csv',gates.rows,['check','passed','expected','actual'])
            manifest['completed_utc']=stamp(datetime.now(UTC))
            dump_json(work/'run_manifest.json',manifest)
            publish(work,success)
            write_status('complete' if success else 'error',progress=100,result_path=RESULT_NAME,
                         frozen_data_key=data_key(),result_sha256=digest((OUT/RESULT_NAME).read_bytes()),manifest=manifest,
                         message='Independent frozen confirmation complete; await review' if success else 'Failed gate; download diagnostic ZIP')
    except Exception:
        # Withhold any stale archive if publication itself fails.
        write_status('error',progress=100,result_path=None,message='Result publication failed; no current ZIP available')
        success=False
    finally:
        if FILE_LOCK is not None:
            FILE_LOCK.close();FILE_LOCK=None
    return success


def launch(background=True):
    global STARTED,FILE_LOCK
    with MUTEX:
        if STARTED:return False
        OUT.mkdir(parents=True,exist_ok=True)
        if os.name=='posix':
            import fcntl
            handle=(OUT/'run.lock').open('a+')
            try:fcntl.flock(handle,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError:handle.close();return False
            FILE_LOCK=handle
        prior=read_status();bundle=OUT/RESULT_NAME
        if (prior.get('state')=='complete' and prior.get('runner_sha256')==runner_hash()
            and prior.get('frozen_data_key')==data_key() and bundle.exists()
            and digest(bundle.read_bytes())==prior.get('result_sha256')):
            STARTED=True
            if FILE_LOCK is not None:FILE_LOCK.close();FILE_LOCK=None
            return False
        STARTED=True
        write_status('starting',progress=0,result_path=None,message='Independent original versus frozen ATR1.50 confirmation')
    if background:
        threading.Thread(target=confirmation_job,name='eurchf-pass11',daemon=True).start()
        return True
    return confirmation_job()


def app(environ,start_response):
    path=environ.get('PATH_INFO','/')
    if path==PREFIX or path.startswith(PREFIX+'/'):path=path[len(PREFIX):] or '/'
    method=environ.get('REQUEST_METHOD','GET')
    code='200 OK'
    if method not in ('GET','HEAD'):
        code,value='405 Method Not Allowed',dict(error='GET or HEAD only')
    elif path not in ('/','/start','/status','/health','/results'):
        code,value='404 Not Found',dict(error='Not found')
    else:
        if method=='GET' and (path=='/start' or os.getenv('EURCHF_PASS11_AUTOSTART','1')=='1') and not STARTED:
            launch()
        value=read_status()
        if path=='/results':
            bundle=OUT/RESULT_NAME
            current=(value.get('state') in ('complete','error') and value.get('runner_sha256')==runner_hash()
                     and value.get('frozen_data_key')==data_key() and value.get('result_path')==RESULT_NAME
                     and bundle.exists() and digest(bundle.read_bytes())==value.get('result_sha256'))
            if current:
                start_response(code,[('Content-Type','application/zip'),('Content-Length',str(bundle.stat().st_size)),
                    ('Content-Disposition',f'attachment; filename="{RESULT_NAME}"'),('Cache-Control','no-store')])
                if method=='HEAD':return []
                def blocks():
                    with bundle.open('rb') as f:
                        while True:
                            block=f.read(1024*1024)
                            if not block:break
                            yield block
                return blocks()
            code='409 Conflict';value=dict(value,error='Results not ready for this exact code and frozen source')
        elif path=='/health':value=dict(ok=True,state=value.get('state'),version=VERSION,orders_supported=False)
        elif path=='/':value=dict(service='EUR/CHF independent frozen original/ATR1.50 confirmation',
                                 version=VERSION,state=value.get('state'),status='/status',results='/results',orders_supported=False)
    body=(json.dumps(value,allow_nan=False)+'\n').encode()
    start_response(code,[('Content-Type','application/json'),('Content-Length',str(len(body))),('Cache-Control','no-store')])
    return [] if method=='HEAD' else [body]


class ConcurrentServer(ThreadingMixIn,WSGIServer):
    daemon_threads=True


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    group=parser.add_mutually_exclusive_group()
    group.add_argument('--run',action='store_true')
    group.add_argument('--self-test',action='store_true')
    args=parser.parse_args()
    if args.self_test:
        print(json.dumps(dict(version=VERSION,market_data_used=False,checks=software_checks()),indent=2));return 0
    if args.run:
        launch(background=False);print(json.dumps(read_status(),indent=2))
        return 0 if read_status().get('state')=='complete' else 1
    if os.getenv('EURCHF_PASS11_AUTOSTART','1')=='1':launch()
    with make_server('0.0.0.0',int(os.getenv('PORT','8080')),app,server_class=ConcurrentServer) as server:
        print(VERSION+': /status and /results',flush=True);server.serve_forever()
    return 0


if __name__=='__main__':
    raise SystemExit(main())
